/**
 * Universal deterministic static flow copy (#559, #561).
 *
 * Framework-level messages (validation errors, navigation hints, reroute prompts,
 * menu chrome, account labels, booking/ordering/payment/ticketing UI, confirmations)
 * that do not contain merchant/transaction data. These bypass LLM translation
 * for reliability — the LLM path remains available for dynamic content.
 *
 * A language's copy may be used ONLY when it is both certified AND effective/entitled
 * for the session's business. Otherwise, falls back to English.
 *
 * Population != certification != activation.
 * Languages may have copy here but remain uncertified (yo, ig, ha, tw, fr, es).
 * Only certified+entitled languages resolve to their locale copy at runtime.
 *
 * Placeholders use {name} syntax. The set must be identical across every locale.
 * Bot commands (*Hi*, *cancel*, *menu*, *back*, *exit*, *skip*) are preserved
 * as English in all locales — inbound normalization handles multilingual input.
 */
import { CERTIFIED_LANGUAGES, SUPPORTED_LANGUAGES } from '@/lib/bot/languages';
import type { SupportedLanguage } from '@/lib/bot/languages';

